Here is the commit message:
smb: server: avoid double-free in smb_direct_free_sendmsg
 after smb_direct_flush_send_list()

smb_direct_flush_send_list() already calls smb_direct_free_sendmsg(),
so we should not call it again after post_sendmsg()
moved it to the batch list.

Reported-by: Ruikai Peng <ruikai@pwno.io>
Closes: https://lore.kernel.org/linux-cifs/CAFD3drNOSJ05y3A+jNXSDxW-2w09KHQ0DivhxQ_pcc7immVVOQ@mail.gmail.com/
Fixes: 34abd408c8ba ("smb: server: make use of smbdirect_socket.send_io.bcredits")
Cc: stable@kernel.org
Cc: Steve French <smfrench@gmail.com>
Cc: Tom Talpey <tom@talpey.com>
Cc: Ruikai Peng <ruikai@pwno.io>
Cc: Sergey Senozhatsky <senozhatsky@chromium.org>
Cc: linux-cifs@vger.kernel.org
Cc: samba-technical@lists.samba.org
Cc: security@kernel.org
Signed-off-by: Stefan Metzmacher <metze@samba.org>
Acked-by: Namjae Jeon <linkinjeon@kernel.org>
Acked-by: Paulo Alcantara (Red Hat) <pc@manguebit.org>
Tested-by: Ruikai Peng <ruikai@pwno.io>
Signed-off-by: Steve French <stfrench@microsoft.com>

Here is the root cause:
In `smb_direct_post_send_data`, after a message is successfully posted via `post_sendmsg()` and moved to the send context, if the subsequent `smb_direct_flush_send_list()` fails, the error handling jumped to label `err`, which unconditionally called `smb_direct_free_sendmsg()` again. However, `smb_direct_flush_send_list()` already calls `smb_direct_free_sendmsg()` internally (either on failure or after transferring ownership), leading to a double-free of the message.

Here is the patch:

 static int smb_direct_post_send_data(struct smbdirect_socket *sc,
 				     struct smbdirect_send_batch *send_ctx,
 				     struct kvec *iov, int niov,
 				     int remaining_data_length)
 {
 	int i, j, ret;
 	struct smbdirect_send_io *msg;
 	int data_length;
 	struct scatterlist sg[SMBDIRECT_SEND_IO_MAX_SGE - 1];
 	struct smbdirect_send_batch _send_ctx;
 	int new_credits;

 	if (!send_ctx) {
 		smb_direct_send_ctx_init(&_send_ctx, false, 0);
 		send_ctx = &_send_ctx;
 	}

 	ret = wait_for_send_bcredit(sc, send_ctx);
 	if (ret)
 		goto bcredit_failed;

 	ret = wait_for_send_lcredit(sc, send_ctx);
 	if (ret)
 		goto lcredit_failed;

 	ret = wait_for_send_credits(sc, send_ctx);
 	if (ret)
 		goto credit_failed;

 	new_credits = manage_credits_prior_sending(sc);
 	if (new_credits == 0 &&
 	    atomic_read(&sc->send_io.credits.count) == 0 &&
 	    atomic_read(&sc->recv_io.credits.count) == 0) {
 		queue_work(sc->workqueue, &sc->recv_io.posted.refill_work);
 		ret = wait_event_interruptible(sc->send_io.credits.wait_queue,
 					       atomic_read(&sc->send_io.credits.count) >= 1 ||
 					       atomic_read(&sc->recv_io.credits.available) >= 1 ||
 					       sc->status != SMBDIRECT_SOCKET_CONNECTED);
 		if (sc->status != SMBDIRECT_SOCKET_CONNECTED)
 			ret = -ENOTCONN;
 		if (ret < 0)
 			goto credit_failed;

 		new_credits = manage_credits_prior_sending(sc);
 	}

 	data_length = 0;
 	for (i = 0; i < niov; i++)
 		data_length += iov[i].iov_len;

 	ret = smb_direct_create_header(sc, data_length, remaining_data_length,
 				       new_credits, &msg);
 	if (ret)
 		goto header_failed;

 	for (i = 0; i < niov; i++) {
 		struct ib_sge *sge;
 		int sg_cnt;
 		int npages;

 		sg_init_table(sg, SMBDIRECT_SEND_IO_MAX_SGE - 1);
 		sg_cnt = get_mapped_sg_list(sc->ib.dev,
 					    iov[i].iov_base, iov[i].iov_len,
 					    sg, SMBDIRECT_SEND_IO_MAX_SGE - 1,
 					    DMA_TO_DEVICE, &npages);
 		if (sg_cnt <= 0) {
 			pr_err("failed to map buffer\n");
 			ret = -ENOMEM;
 			goto err;
 		} else if (sg_cnt + msg->num_sge > SMBDIRECT_SEND_IO_MAX_SGE) {
 			pr_err("buffer not fitted into sges\n");
 			ret = -E2BIG;
 			ib_dma_unmap_sg(sc->ib.dev, sg, npages,
 					DMA_TO_DEVICE);
 			goto err;
 		}

 		for (j = 0; j < sg_cnt; j++) {
 			sge = &msg->sge[msg->num_sge];
 			sge->addr = sg_dma_address(&sg[j]);
 			sge->length = sg_dma_len(&sg[j]);
 			sge->lkey  = sc->ib.pd->local_dma_lkey;
 			msg->num_sge++;
 		}
 	}

 	ret = post_sendmsg(sc, send_ctx, msg);
 	if (ret)
 		goto err;

+	/*
+	 * From here msg is moved to send_ctx
+	 * and we should not free it explicitly.
+	 */
+
 	if (send_ctx == &_send_ctx) {
 		ret = smb_direct_flush_send_list(sc, send_ctx, true);
 		if (ret)
-			goto err;
+			goto flush_failed;
 	}

 	return 0;
 err:
 	smb_direct_free_sendmsg(sc, msg);
+flush_failed:
 header_failed:
 	atomic_inc(&sc->send_io.credits.count);
 credit_failed:
 	atomic_inc(&sc->send_io.lcredits.count);
 lcredit_failed:
 	atomic_add(send_ctx->credit, &sc->send_io.bcredits.count);
 	send_ctx->credit = 0;
 bcredit_failed:
 	return ret;
 }



